// LoopAgent extends BaseAgent:
export class LoopAgent extends BaseAgent {
  readonly [LOOP_AGENT_SIGNATURE_SYMBOL] = true;
  protected async *runAsyncImpl(context: InvocationContext): AsyncGenerator<Event> {
    for (iteration = 0; iteration < maxIterations; iteration++) {
      for (const subAgent of this.subAgents) {
        for await (const event of subAgent.runAsync(context)) {
          yield event;
          if (event.actions.escalate) return;
        }
      }
    }
  }
}

