// Generator wrapping for OpenTelemetry:
export async function* runAsyncGeneratorWithOtelContext<T, U>(
  ctx: Context,
  thisArg: T,
  generator: () => AsyncGenerator<U>,
): AsyncGenerator<U> {
  const boundGenerator = context.bind(ctx, generator);
  for await (const item of boundGenerator.call(thisArg)) {
    yield item;
  }
}

// Template Method in BaseAgent:
async *runAsync(parentContext: InvocationContext): AsyncGenerator<Event> {
  // Template defines skeleton
  const beforeEvent = await this.handleBeforeAgentCallback(context);
  if (beforeEvent) yield beforeEvent;

  // Hook point - subclasses implement
  for await (const event of this.runAsyncImpl(context)) {
    yield event;
  }

  const afterEvent = await this.handleAfterAgentCallback(context);
  if (afterEvent) yield afterEvent;
}

