// Registry/Factory pattern:
export class LLMRegistry {
  private static modelRegistries = new Map<RegExp, BaseLlmType>();
  private static cache = new LRUCache<string, BaseLlm>(100);

  static register(supportedModels: (string | RegExp)[], llmType: BaseLlmType) {
    for (const pattern of supportedModels) {
      this.modelRegistries.set(new RegExp(pattern), llmType);
    }
  }

  static resolve(model: string): BaseLlmType | undefined {
    for (const [pattern, llmType] of this.modelRegistries) {
      if (pattern.test(model)) return llmType;
    }
  }

  static newLlm(model: string): BaseLlm {
    if (this.cache.has(model)) return this.cache.get(model)!;
    const llmType = this.resolve(model);
    const instance = new llmType({ model });
    this.cache.set(model, instance);
    return instance;
  }
}

// State class with value/delta tracking:
export class State {
  static readonly APP_PREFIX = 'app:';
  static readonly USER_PREFIX = 'user:';
  static readonly TEMP_PREFIX = 'temp:';

  constructor(
    private value: Record<string, unknown> = {},
    private delta: Record<string, unknown> = {},
  ) {}

  get<T>(key: string, defaultValue?: T): T | undefined {
    if (key in this.delta) return this.delta[key] as T; // Delta first
    if (key in this.value) return this.value[key] as T;
    return defaultValue;
  }

  set(key: string, value: unknown) {
    this.value[key] = value;
    this.delta[key] = value; // Track change
  }

  hasDelta(): boolean {
    return Object.keys(this.delta).length > 0;
  }
}

