// AgentTransferLlmRequestProcessor:
class AgentTransferLlmRequestProcessor extends BaseLlmRequestProcessor {
  private readonly toolName = 'transfer_to_agent' as const;
  private readonly tool = new FunctionTool({
    name: this.toolName,
    description:
      'Transfer the question to another agent. This tool hands off control to another agent when it is more suitable to answer the user question according to the agent description.',
    parameters: z.object({
      agentName: z.string().describe('the agent name to transfer to.'),
    }),
    execute: async ({agentName}, toolContext) => {
      return transferToAgent(agentName, this.agent, toolContext);
    },
  });

  async *runAsync(context, llmRequest) {
    if (this.shouldAddTransferTool(this.agent)) {
      llmRequest.toolsDict[this.toolName] = this.tool;
    }
  }

  private shouldAddTransferTool(agent: LlmAgent): boolean {
    return !agent.outputSchema && // No output schema
      (agent.parentAgent !== undefined || agent.subAgents.length > 0);
  }
}

// Transfer target determination:
function getTransferTargets(agent: LlmAgent): string[] {
  const targets: string[] = [];

  // Parent agent
  if (agent.parentAgent && !agent.disallowTransferToParent) {
    targets.push(agent.parentAgent.name);
  }

  // Peer agents
  if (agent.parentAgent && !agent.disallowTransferToPeers) {
    for (const peer of agent.parentAgent.subAgents) {
      if (peer.name !== agent.name) {
        targets.push(peer.name);
      }
    }
  }

  // Sub-agents (always available)
  for (const subAgent of agent.subAgents) {
    targets.push(subAgent.name);
  }

  return targets;
}

// Transfer execution:
async function transferToAgent(
  agentName: string,
  agent: LlmAgent,
  toolContext: ToolContext,
): Promise<Record<string, unknown>> {
  const targets = getTransferTargets(agent);
  if (!targets.includes(agentName)) {
    throw new Error(`Invalid transfer target: ${agentName}`);
  }

  toolContext.eventActions.transferToAgent = agentName;
  return {result: `Transferred to agent: ${agentName}`};
}

// LoopAgent implementation:
export interface LoopAgentConfig extends BaseAgentConfig {
  maxIterations?: number;
}

export class LoopAgent extends BaseAgent {
  private readonly maxIterations: number;

  constructor(config: LoopAgentConfig) {
    super(config);
    this.maxIterations = config.maxIterations ?? Number.MAX_SAFE_INTEGER;
  }

  protected async *runAsyncImpl(
    context: InvocationContext,
  ): AsyncGenerator<Event, void, void> {
    let iteration = 0;

    while (iteration < this.maxIterations) {
      for (const subAgent of this.subAgents) {
        let shouldExit = false;
        for await (const event of subAgent.runAsync(context)) {
          yield event;

          if (event.actions.escalate) {
            shouldExit = true; // Escalate exits loop
          }
        }

        if (shouldExit) {
          return; // Exit entire loop
        }
      }

      iteration++;
    }

    return;
  }
}

// ParallelAgent implementation:
export class ParallelAgent extends BaseAgent {
  protected async *runAsyncImpl(
    context: InvocationContext,
  ): AsyncGenerator<Event, void, void> {
    const agentRuns = this.subAgents.map((subAgent) =>
      subAgent.runAsync(createBranchCtxForSubAgent(this, subAgent, context)),
    );

    for await (const event of mergeAgentRuns(agentRuns)) {
      yield event;
    }
  }
}

// Branch context creation:
function createBranchCtxForSubAgent(
  agent: BaseAgent,
  subAgent: BaseAgent,
  originalContext: InvocationContext,
): InvocationContext {
  const invocationContext = new InvocationContext(originalContext);
  const branchSuffix = `${agent.name}.${subAgent.name}`;
  invocationContext.branch = invocationContext.branch
    ? `${invocationContext.branch}.${branchSuffix}`
    : branchSuffix;

  return invocationContext;
}

// Event merging with Promise.race:
async function* mergeAgentRuns(
  agentRuns: AsyncGenerator<Event, void, void>[],
): AsyncGenerator<Event, void, void> {
  const pendingPromises = new Map<number, Promise<IteratorResult<Event>>>();

  // Initialize promises
  for (let i = 0; i < agentRuns.length; i++) {
    pendingPromises.set(i, agentRuns[i].next());
  }

  while (pendingPromises.size > 0) {
    // Race to find next completed
    const {index, result} = await Promise.race(
      Array.from(pendingPromises.entries()).map(([i, p]) => 
        p.then(result => ({index: i, result}))
      )
    );

    if (result.done) {
      pendingPromises.delete(index); // Generator finished
    } else {
      yield result.value; // Yield event
      pendingPromises.set(index, agentRuns[index].next()); // Advance generator
    }
  }
}

// Agent name validation:
function validateAgentName(name: string): string {
  if (!isIdentifier(name)) {
    throw new Error(
      `Found invalid agent name: "${
        name
      }". Agent name must be a valid identifier. It should start with a letter (a-z, A-Z) or an underscore (_), and can only contain letters, digits (0-9), underscores, and hyphens.`,
    );
  }

  if (name === 'user') {
    throw new Error(
      `Agent name cannot be 'user'. 'user' is reserved for end-user's input.`,
    );
  }

  return name;
}

function isIdentifier(str: string): boolean {
  return /^[\p{ID_Start}$_][\p{ID_Continue}$_-]*$/u.test(str);
}

