// Callback type definitions:
export type SingleAgentCallback = (
  context: CallbackContext,
) => Promise<Content | undefined> | (Content | undefined);

export type BeforeAgentCallback = SingleAgentCallback | SingleAgentCallback[];
export type AfterAgentCallback = SingleAgentCallback | SingleAgentCallback[];

// BaseAgentConfig:
export interface BaseAgentConfig {
  beforeAgentCallback?: BeforeAgentCallback;
  afterAgentCallback?: AfterAgentCallback;
}

// Execution in runAsync():
async *runAsync(parentContext: InvocationContext): AsyncGenerator<Event, void, void> {
  const context = this.createInvocationContext(parentContext);

  // Before callback
  const beforeAgentCallbackEvent = await this.handleBeforeAgentCallback(context);
  if (beforeAgentCallbackEvent) {
    yield beforeAgentCallbackEvent;
  }

  if (context.endInvocation) {
    return; // Early exit if callback returned content
  }

  // Run agent implementation
  for await (const event of this.runAsyncImpl(context)) {
    yield event;
  }

  if (context.endInvocation) {
    return;
  }

  // After callback
  const afterAgentCallbackEvent = await this.handleAfterAgentCallback(context);
  if (afterAgentCallbackEvent) {
    yield afterAgentCallbackEvent;
  }
}

// handleBeforeAgentCallback with early-exit:
async handleBeforeAgentCallback(
  invocationContext: InvocationContext,
): Promise<Event | undefined> {
  const callbackContext = new CallbackContext({ invocationContext });

  // Run plugin callbacks first
  const pluginResult = await invocationContext.pluginManager.runBeforeAgentCallbacks(
    callbackContext,
  );
  if (pluginResult) {
    invocationContext.endInvocation = true; // Early exit
    return createEvent({
      author: this.name,
      content: pluginResult,
      actions: callbackContext.eventActions,
    });
  }

  // Run agent callbacks
  for (const callback of this.beforeAgentCallback) {
    const result = await callback(callbackContext);
    if (result !== undefined) {
      invocationContext.endInvocation = true; // Early exit
      return createEvent({
        author: this.name,
        content: result,
        actions: callbackContext.eventActions,
      });
    }
  }

  return undefined;
}

