// InstructionsLlmRequestProcessor:
class InstructionsLlmRequestProcessor extends BaseLlmRequestProcessor {
  async *runAsync(context, llmRequest) {
    const readonlyContext = new ReadonlyContext(context);

    // Global instruction (root agent only)
    const rootAgent = context.agent.rootAgent;
    if (isLlmAgent(rootAgent)) {
      const {instruction: globalInstruction, requireStateInjection} =
        await rootAgent.canonicalGlobalInstruction(readonlyContext);

      let instructionWithState = globalInstruction;
      if (requireStateInjection) {
        instructionWithState = await injectSessionState(
          globalInstruction,
          readonlyContext,
        );
      }
      appendInstructions(llmRequest, instructionWithState);
    }

    // Agent instruction
    const {instruction, requireStateInjection: reqStateInjection} =
      await agent.canonicalInstruction(readonlyContext);

    let instructionWithState = instruction;
    if (reqStateInjection) {
      instructionWithState = await injectSessionState(
        instruction,
        readonlyContext,
      );
    }
    appendInstructions(llmRequest, instructionWithState);
  }
}

// injectSessionState template syntax:
export async function injectSessionState(
  template: string,
  readonlyContext: ReadonlyContext,
): Promise<string> {
  // Matches {key}, {app:key}, {user:key}, {temp:key}, {artifact.file}, {key?}
  const pattern = /\{+[^{}]*}+/g;

  async function replaceMatchedKeyWithItsValue(match: RegExpMatchArray) {
    let key = match[0].replace(/^\{+/, '').replace(/\}+$/, '').trim();
    const isOptional = key.endsWith('?');
    if (isOptional) key = key.slice(0, -1);

    // Handle artifact injection
    if (key.startsWith('artifact.')) {
      const fileName = key.substring('artifact.'.length);
      const artifact = await artifactService.loadArtifact({...fileName});
      if (!artifact) throw new Error(`Artifact ${fileName} not found.`);
      return String(artifact);
    }

    // Handle state variable
    if (key in session.state) {
      return String(session.state[key]);
    }

    if (isOptional) return '';
    throw new Error(`Context variable not found: \`${key}\`.`);
  }

  // Replace all matches
  for (const match of template.matchAll(pattern)) {
    const replacement = await replaceMatchedKeyWithItsValue(match);
    // ... replace in template
  }
}

// LlmAgentConfig:
export interface LlmAgentConfig extends BaseAgentConfig {
  outputSchema?: Schema;
  outputKey?: string;
}

// maybeSaveOutputToState implementation:
private maybeSaveOutputToState(event: Event) {
  // Skip if streaming
  if (event.partial) {
    logger.debug(
      `Skipping output save for agent ${this.name}: event is partial`,
    );
    return;
  }

  if (!this.outputKey) {
    logger.debug(
      `Skipping output save for agent ${this.name}: outputKey is not set`,
    );
    return;
  }

  if (!isFinalResponse(event)) {
    logger.debug(
      `Skipping output save for agent ${this.name}: event is not final response`,
    );
    return;
  }

  // Extract text from content
  const text = event.content?.parts
    ?.map((part) => part.text || '')
    .join('')
    .trim();

  if (!text) {
    logger.warn(
      `No text content found in final response for agent ${this.name}`,
    );
    return;
  }

  let result: unknown = text;

  // If outputSchema is set, try to parse as JSON
  if (this.outputSchema) {
    try {
      result = JSON.parse(text);
    } catch (error) {
      logger.error(
        `Failed to parse output as JSON for agent ${this.name}:`,
        error,
      );
      return;
    }
  }

  // Save to state
  event.actions.stateDelta[this.outputKey] = result;
  logger.debug(
    `Saved output to state for agent ${this.name} with key ${this.outputKey}`,
  );
}

// Called in runAsyncImpl after response:
if (isFinalResponse(event)) {
  this.maybeSaveOutputToState(event);
}

// outputSchema disables tools:
private shouldAddTransferTool(agent: LlmAgent): boolean {
  return !agent.outputSchema && // No tools when outputSchema set
    (agent.parentAgent !== undefined || agent.subAgents.length > 0);
}

// canonicalModel getter:
get canonicalModel(): BaseLlm {
  // 1. Direct BaseLlm instance
  if (isBaseLlm(this.model)) {
    return this.model;
  }

  // 2. Model string -> create from registry
  if (typeof this.model === 'string' && this.model) {
    return LLMRegistry.newLlm(this.model);
  }

  // 3. Inherit from ancestor
  let ancestorAgent = this.parentAgent;
  while (ancestorAgent) {
    if (isLlmAgent(ancestorAgent)) {
      return ancestorAgent.canonicalModel; // Recursive call
    }
    ancestorAgent = ancestorAgent.parentAgent;
  }

  // 4. No model found
  throw new Error(`No model found for ${this.name}.`);
}

// LLMRegistry.newLlm with caching:
static newLlm(model: string): BaseLlm {
  // Check cache first
  if (this.cache.has(model)) {
    return this.cache.get(model)!;
  }

  // Resolve model type
  const llmType = this.resolve(model);
  if (!llmType) {
    throw new Error(`No LLM type found for model: ${model}`);
  }

  // Create instance
  const instance = new llmType({ model });
  this.cache.set(model, instance);

  return instance;
}

