// LlmAgentConfig:
export interface LlmAgentConfig extends BaseAgentConfig {
  includeContents?: 'default' | 'none';
}

// ContentRequestProcessor:
class ContentRequestProcessor implements BaseLlmRequestProcessor {
  async *runAsync(
    invocationContext: InvocationContext,
    llmRequest: LlmRequest,
  ): AsyncGenerator<Event, void, void> {
    const agent = invocationContext.agent;
    if (!agent || !isLlmAgent(agent)) {
      return;
    }

    if (agent.includeContents === 'default') {
      // Include full conversation history
      llmRequest.contents = getContents(
        invocationContext.session.events,
        agent.name,
        invocationContext.branch,
      );
    } else {
      // Include current turn context only (no conversation history)
      llmRequest.contents = getCurrentTurnContents(
        invocationContext.session.events,
        agent.name,
        invocationContext.branch,
      );
    }

    return;
  }
}

// getContents filters full history:
export function getContents(
  events: Event[],
  agentName: string,
  branch?: string,
): Content[] {
  return events
    .filter(event => {
      // Filter by branch
      if (branch && event.branch !== branch) return false;
      // Include user messages and agent messages
      if (event.author === 'user' || event.author === agentName) return true;
      // Include relevant function responses
      return hasFunctionResponseForAgent(event, agentName);
    })
    .map(event => event.content)
    .filter(content => content !== undefined);
}

// getCurrentTurnContents returns current turn only:
export function getCurrentTurnContents(
  events: Event[],
  agentName: string,
  branch?: string,
): Content[] {
  // Find most recent user message
  const lastUserEventIndex = findLastIndex(
    events,
    e => e.author === 'user' && (!branch || e.branch === branch),
  );

  if (lastUserEventIndex === -1) return [];

  // Return events from last user message onwards
  return events
    .slice(lastUserEventIndex)
    .filter(e => !branch || e.branch === branch)
    .map(e => e.content)
    .filter(c => c !== undefined);
}
